 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))

    # Locate the embedded three-cell pattern: a contiguous non-background
    # triplet on one row or column. The pattern itself is preserved.
    candidates = []
    for r in range(h):
        for c in range(w - 2):
            vals = [grid[r][c + i] for i in range(3)]
            if all(v != bg for v in vals):
                candidates.append((r, c, 0, 1, vals))
    for r in range(h - 2):
        for c in range(w):
            vals = [grid[r + i][c] for i in range(3)]
            if all(v != bg for v in vals):
                candidates.append((r, c, 1, 0, vals))
    if not candidates:
        return [row[:] for row in grid]
    # The embedded pattern is at the border in these tasks; prefer that
    # location and then the most distinctive triplet.
    def score(item):
        r, c, dr, dc, vals = item
        edge = min(r, c, h - 1 - (r + 2 * dr), w - 1 - (c + 2 * dc))
        return (-edge, len(set(vals)))
    sr, sc, dr, dc, pattern = max(candidates, key=score)
    source = {(sr + i * dr, sc + i * dc) for i in range(3)}

    # Pick the most frequent non-background color outside the pattern as
    # the repeated marker.
    counts = {}
    for r in range(h):
        for c in range(w):
            if (r, c) not in source and grid[r][c] != bg:
                counts[grid[r][c]] = counts.get(grid[r][c], 0) + 1
    if not counts:
        return [row[:] for row in grid]
    marker = max(counts, key=counts.get)
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == marker and (r, c) not in source:
                for i, color in enumerate(pattern):
                    rr = r + (i - 1) * dr
                    cc = c + (i - 1) * dc
                    if 0 <= rr < h and 0 <= cc < w:
                        out[rr][cc] = color
    return out
