 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    # Connected non-background components. The largest is the stamp; isolated
    # components of a repeated color are locations at which to place it.
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                rr, cc = stack.pop()
                comp.append((rr, cc))
                for nr, nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] != bg and (nr,nc) not in seen:
                        seen.add((nr,nc))
                        stack.append((nr,nc))
            comps.append(comp)
    if not comps:
        return [row[:] for row in grid]
    source = max(comps, key=len)
    sr = min(r for r,c in source); er = max(r for r,c in source)
    sc = min(c for r,c in source); ec = max(c for r,c in source)
    ar, ac = (sr+er)//2, (sc+ec)//2
    source_set = set(source)

    # Repeated isolated non-background cells mark stamp centers.
    marker_counts = {}
    for comp in comps:
        if len(comp) == 1 and comp[0] not in source_set:
            r,c = comp[0]
            marker_counts[grid[r][c]] = marker_counts.get(grid[r][c], 0) + 1
    if not marker_counts:
        return [row[:] for row in grid]
    marker = max(marker_counts, key=marker_counts.get)
    targets = [(r,c) for comp in comps if len(comp)==1
               for r,c in comp if grid[r][c]==marker and (r,c) not in source_set]

    out = [row[:] for row in grid]
    for tr, tc in targets:
        for r,c in source:
            rr, cc = tr + r-ar, tc + c-ac
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = grid[r][c]
    return out
